<section class="lm2-auth-page" aria-labelledby="login-title"><div class="lm2-auth-shell"><div class="lm2-auth-intro"><span class="lm2-eyebrow">Welcome back</span><h1 id="login-title">Welcome to your next chapter.</h1><p>Your courses, progress and learning community are just a sign in away.</p><div class="lm2-auth-stats"><span class="lm2-auth-bullet">✓</span> Learn at your own pace</div></div><div class="lm2-auth-card"><span class="lm2-eyebrow">Account access</span><h2>Sign in</h2><p>Continue where you left off.</p><?php if ($error): ?><div class="lm-notice lm-notice-error" role="alert"><?= e($error) ?></div><?php endif; ?><form action="/login" method="post"><?= csrf_field() ?><div class="lm2-form-field"><label for="login-email">Email address</label><input id="login-email" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="lm2-form-field"><label for="login-password">Password</label><div class="lm-password-wrap"><input id="login-password" name="password" type="password" required autocomplete="current-password" placeholder="Enter your password"><button type="button" class="lm-password-toggle" data-password-toggle="login-password" aria-controls="login-password" aria-pressed="false">Show</button></div></div><button class="lm-button lm-button-primary lm2-auth-submit" type="submit">Sign in →</button></form><div class="lm2-auth-foot">New to Learmingo? <a href="/register">Create your account</a></div></div></div></section>
